window.NLT = {"duration":302.75,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if there was no light in the universe?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.307},{"text":"there","start":0.563},{"text":"was","start":0.82},{"text":"no","start":1.077},{"text":"light","start":1.333},{"text":"in","start":1.59},{"text":"the","start":1.847},{"text":"universe?","start":2.103}]}]},{"id":"start","n":2,"section":1,"title":false,"first":3.85,"end":18.25,"caps":[{"text":"2:40 PM, on a frozen lake in Norway. Every light in the universe just went out.","show":3.85,"hide":8.8,"words":[{"text":"2:40","start":3.85},{"text":"PM,","start":4.067},{"text":"on","start":4.283},{"text":"a","start":4.5},{"text":"frozen","start":4.716},{"text":"lake","start":4.933},{"text":"in","start":5.149},{"text":"Norway.","start":5.366},{"text":"Every","start":5.583},{"text":"light","start":5.799},{"text":"in","start":6.016},{"text":"the","start":6.232},{"text":"universe","start":6.449},{"text":"just","start":6.665},{"text":"went","start":6.882},{"text":"out.","start":7.098}]},{"text":"Not a power cut. The Sun is still in the sky.","show":9.8,"hide":13.05,"words":[{"text":"Not","start":9.8},{"text":"a","start":10.007},{"text":"power","start":10.214},{"text":"cut.","start":10.42},{"text":"The","start":10.627},{"text":"Sun","start":10.834},{"text":"is","start":11.041},{"text":"still","start":11.248},{"text":"in","start":11.455},{"text":"the","start":11.661},{"text":"sky.","start":11.868}]},{"text":"Your eyes are wide open. There's nothing left for them to catch.","show":14.05,"hide":18.25,"words":[{"text":"Your","start":14.05},{"text":"eyes","start":14.295},{"text":"are","start":14.54},{"text":"wide","start":14.785},{"text":"open.","start":15.03},{"text":"There's","start":15.275},{"text":"nothing","start":15.52},{"text":"left","start":15.765},{"text":"for","start":16.01},{"text":"them","start":16.255},{"text":"to","start":16.5},{"text":"catch.","start":16.745}]}]},{"id":"skaters","n":3,"section":1,"title":false,"first":19.05,"end":27.5,"caps":[{"text":"You're still gliding at 21 km/h on two thin blades. So is everyone around you.","show":19.05,"hide":23.95,"words":[{"text":"You're","start":19.05},{"text":"still","start":19.279},{"text":"gliding","start":19.507},{"text":"at","start":19.736},{"text":"21","start":19.965},{"text":"km/h","start":20.193},{"text":"on","start":20.422},{"text":"two","start":20.651},{"text":"thin","start":20.879},{"text":"blades.","start":21.108},{"text":"So","start":21.337},{"text":"is","start":21.565},{"text":"everyone","start":21.794},{"text":"around","start":22.023},{"text":"you.","start":22.251}]},{"text":"And nobody can see.","show":25.55,"hide":27.5,"words":[{"text":"And","start":25.55},{"text":"nobody","start":25.891},{"text":"can","start":26.233},{"text":"see.","start":26.574}]}]},{"id":"heat","n":4,"section":1,"title":false,"first":29.9,"end":40.3,"caps":[{"text":"But everything still glows, in a light no eye can see: infrared.","show":29.9,"hide":34.1,"words":[{"text":"But","start":29.9},{"text":"everything","start":30.145},{"text":"still","start":30.39},{"text":"glows,","start":30.635},{"text":"in","start":30.88},{"text":"a","start":31.125},{"text":"light","start":31.37},{"text":"no","start":31.615},{"text":"eye","start":31.86},{"text":"can","start":32.105},{"text":"see:","start":32.35},{"text":"infrared.","start":32.595}]},{"text":"This is what a heat camera would see. Nobody on this lake can see any of it.","show":35.5,"hide":40.3,"words":[{"text":"This","start":35.5},{"text":"is","start":35.698},{"text":"what","start":35.895},{"text":"a","start":36.093},{"text":"heat","start":36.291},{"text":"camera","start":36.488},{"text":"would","start":36.686},{"text":"see.","start":36.884},{"text":"Nobody","start":37.081},{"text":"on","start":37.279},{"text":"this","start":37.476},{"text":"lake","start":37.674},{"text":"can","start":37.872},{"text":"see","start":38.069},{"text":"any","start":38.267},{"text":"of","start":38.465},{"text":"it.","start":38.662}]}]},{"id":"rule","n":5,"section":1,"title":false,"first":41.5,"end":57,"caps":[{"text":"Light is one kind of electromagnetism. Take all of it away, and the force that holds your atoms together goes too.","show":41.5,"hide":46.9,"words":[{"text":"Light","start":41.5},{"text":"is","start":41.68},{"text":"one","start":41.86},{"text":"kind","start":42.04},{"text":"of","start":42.22},{"text":"electromagnetism.","start":42.4},{"text":"Take","start":42.58},{"text":"all","start":42.76},{"text":"of","start":42.94},{"text":"it","start":43.12},{"text":"away,","start":43.3},{"text":"and","start":43.48},{"text":"the","start":43.66},{"text":"force","start":43.84},{"text":"that","start":44.02},{"text":"holds","start":44.2},{"text":"your","start":44.38},{"text":"atoms","start":44.56},{"text":"together","start":44.74},{"text":"goes","start":44.92},{"text":"too.","start":45.1}]},{"text":"You wouldn't be in the dark. You'd be dust.","show":47.9,"hide":51.05,"words":[{"text":"You","start":47.9},{"text":"wouldn't","start":48.145},{"text":"be","start":48.39},{"text":"in","start":48.635},{"text":"the","start":48.88},{"text":"dark.","start":49.125},{"text":"You'd","start":49.37},{"text":"be","start":49.615},{"text":"dust.","start":49.86}]},{"text":"So only the light eyes use is gone: 380 to 750 nanometres. Everywhere, at once.","show":52.05,"hide":57,"words":[{"text":"So","start":52.05},{"text":"only","start":52.281},{"text":"the","start":52.512},{"text":"light","start":52.743},{"text":"eyes","start":52.974},{"text":"use","start":53.205},{"text":"is","start":53.436},{"text":"gone:","start":53.667},{"text":"380","start":53.898},{"text":"to","start":54.129},{"text":"750","start":54.36},{"text":"nanometres.","start":54.591},{"text":"Everywhere,","start":54.822},{"text":"at","start":55.053},{"text":"once.","start":55.284}]}]},{"id":"body","n":6,"section":1,"title":false,"first":58.4,"end":68.7,"caps":[{"text":"Your skin glows brightest at 9.5 micrometres. 13 times too long for any eye.","show":58.4,"hide":63.2,"words":[{"text":"Your","start":58.4},{"text":"skin","start":58.64},{"text":"glows","start":58.88},{"text":"brightest","start":59.12},{"text":"at","start":59.36},{"text":"9.5","start":59.6},{"text":"micrometres.","start":59.84},{"text":"13","start":60.08},{"text":"times","start":60.32},{"text":"too","start":60.56},{"text":"long","start":60.8},{"text":"for","start":61.04},{"text":"any","start":61.28},{"text":"eye.","start":61.52}]},{"text":"Where your hand touched the ice, the ice is still glowing.","show":64.8,"hide":68.7,"words":[{"text":"Where","start":64.8},{"text":"your","start":65.048},{"text":"hand","start":65.296},{"text":"touched","start":65.545},{"text":"the","start":65.793},{"text":"ice,","start":66.041},{"text":"the","start":66.289},{"text":"ice","start":66.537},{"text":"is","start":66.785},{"text":"still","start":67.034},{"text":"glowing.","start":67.282}]}]},{"id":"count","n":7,"section":1,"title":false,"first":70.1,"end":79.7,"caps":[{"text":"240 people were skating here. Every one of them is out on the ice, in the dark.","show":70.1,"hide":75.05,"words":[{"text":"240","start":70.1},{"text":"people","start":70.304},{"text":"were","start":70.508},{"text":"skating","start":70.711},{"text":"here.","start":70.915},{"text":"Every","start":71.119},{"text":"one","start":71.323},{"text":"of","start":71.527},{"text":"them","start":71.731},{"text":"is","start":71.934},{"text":"out","start":72.138},{"text":"on","start":72.342},{"text":"the","start":72.546},{"text":"ice,","start":72.75},{"text":"in","start":72.954},{"text":"the","start":73.157},{"text":"dark.","start":73.361}]},{"text":"It's −12 °C. Nobody knows which way the shore is.","show":76.25,"hide":79.7,"words":[{"text":"It's","start":76.25},{"text":"−12","start":76.492},{"text":"°C.","start":76.733},{"text":"Nobody","start":76.975},{"text":"knows","start":77.216},{"text":"which","start":77.458},{"text":"way","start":77.699},{"text":"the","start":77.941},{"text":"shore","start":78.182},{"text":"is.","start":78.424}]}]},{"id":"grab","n":8,"section":1,"title":false,"first":82.3,"end":90.25,"caps":[{"text":"Someone just grabbed your arm.","show":82.3,"hide":84.8,"words":[{"text":"Someone","start":82.3},{"text":"just","start":82.65},{"text":"grabbed","start":83},{"text":"your","start":83.35},{"text":"arm.","start":83.7}]},{"text":"She was skating behind you. She can't see you either.","show":86.6,"hide":90.25,"words":[{"text":"She","start":86.6},{"text":"was","start":86.855},{"text":"skating","start":87.111},{"text":"behind","start":87.366},{"text":"you.","start":87.622},{"text":"She","start":87.878},{"text":"can't","start":88.133},{"text":"see","start":88.389},{"text":"you","start":88.644},{"text":"either.","start":88.899}]}]},{"id":"help","n":9,"section":1,"title":false,"first":91.65,"end":102.15,"caps":[{"text":"She's calling for help by feel: five presses on the side button. So is everyone else in Norway.","show":91.65,"hide":97.05,"words":[{"text":"She's","start":91.65},{"text":"calling","start":91.86},{"text":"for","start":92.07},{"text":"help","start":92.28},{"text":"by","start":92.49},{"text":"feel:","start":92.7},{"text":"five","start":92.91},{"text":"presses","start":93.12},{"text":"on","start":93.33},{"text":"the","start":93.54},{"text":"side","start":93.75},{"text":"button.","start":93.96},{"text":"So","start":94.17},{"text":"is","start":94.38},{"text":"everyone","start":94.59},{"text":"else","start":94.8},{"text":"in","start":95.01},{"text":"Norway.","start":95.22}]},{"text":"Every ambulance driver is blind too. Nobody is coming.","show":98.45,"hide":102.15,"words":[{"text":"Every","start":98.45},{"text":"ambulance","start":98.738},{"text":"driver","start":99.026},{"text":"is","start":99.313},{"text":"blind","start":99.601},{"text":"too.","start":99.889},{"text":"Nobody","start":100.177},{"text":"is","start":100.464},{"text":"coming.","start":100.752}]}]},{"id":"sun","n":10,"section":1,"title":false,"first":103.75,"end":119.3,"caps":[{"text":"The Sun is less than 3° above the hills. You can still feel it on your face.","show":103.75,"hide":108.55,"words":[{"text":"The","start":103.75},{"text":"Sun","start":103.948},{"text":"is","start":104.145},{"text":"less","start":104.343},{"text":"than","start":104.541},{"text":"3°","start":104.738},{"text":"above","start":104.936},{"text":"the","start":105.134},{"text":"hills.","start":105.331},{"text":"You","start":105.529},{"text":"can","start":105.726},{"text":"still","start":105.924},{"text":"feel","start":106.122},{"text":"it","start":106.319},{"text":"on","start":106.517},{"text":"your","start":106.715},{"text":"face.","start":106.912}]},{"text":"More than half of its energy still gets here, as infrared. Only the part you could see is gone.","show":109.75,"hide":115.15,"words":[{"text":"More","start":109.75},{"text":"than","start":109.949},{"text":"half","start":110.148},{"text":"of","start":110.347},{"text":"its","start":110.546},{"text":"energy","start":110.745},{"text":"still","start":110.944},{"text":"gets","start":111.143},{"text":"here,","start":111.342},{"text":"as","start":111.541},{"text":"infrared.","start":111.739},{"text":"Only","start":111.938},{"text":"the","start":112.137},{"text":"part","start":112.336},{"text":"you","start":112.535},{"text":"could","start":112.734},{"text":"see","start":112.933},{"text":"is","start":113.132},{"text":"gone.","start":113.331}]},{"text":"It sets at 3:29 PM. Nobody will see it.","show":116.35,"hide":119.3,"words":[{"text":"It","start":116.35},{"text":"sets","start":116.579},{"text":"at","start":116.809},{"text":"3:29","start":117.038},{"text":"PM.","start":117.268},{"text":"Nobody","start":117.497},{"text":"will","start":117.727},{"text":"see","start":117.956},{"text":"it.","start":118.186}]}]},{"id":"fire","n":11,"section":1,"title":false,"first":120.9,"end":137.75,"caps":[{"text":"The bonfire by the kiosk is still burning at 800 °C. It makes no light at all.","show":120.9,"hide":125.8,"words":[{"text":"The","start":120.9},{"text":"bonfire","start":121.102},{"text":"by","start":121.304},{"text":"the","start":121.505},{"text":"kiosk","start":121.707},{"text":"is","start":121.909},{"text":"still","start":122.111},{"text":"burning","start":122.312},{"text":"at","start":122.514},{"text":"800","start":122.716},{"text":"°C.","start":122.918},{"text":"It","start":123.119},{"text":"makes","start":123.321},{"text":"no","start":123.523},{"text":"light","start":123.725},{"text":"at","start":123.926},{"text":"all.","start":124.128}]},{"text":"A man is walking straight towards it.","show":127.2,"hide":130.05,"words":[{"text":"A","start":127.2},{"text":"man","start":127.485},{"text":"is","start":127.77},{"text":"walking","start":128.055},{"text":"straight","start":128.34},{"text":"towards","start":128.625},{"text":"it.","start":128.91}]},{"text":"He feels it a metre away, and stops. Fire you can't see is still fire.","show":133.25,"hide":137.75,"words":[{"text":"He","start":133.25},{"text":"feels","start":133.46},{"text":"it","start":133.67},{"text":"a","start":133.88},{"text":"metre","start":134.09},{"text":"away,","start":134.3},{"text":"and","start":134.51},{"text":"stops.","start":134.72},{"text":"Fire","start":134.93},{"text":"you","start":135.14},{"text":"can't","start":135.35},{"text":"see","start":135.56},{"text":"is","start":135.77},{"text":"still","start":135.98},{"text":"fire.","start":136.19}]}]},{"id":"town","n":12,"section":1,"title":false,"first":139.15,"end":148.85,"caps":[{"text":"Every lamp in town is still switched on. All they make now is heat.","show":139.15,"hide":143.5,"words":[{"text":"Every","start":139.15},{"text":"lamp","start":139.368},{"text":"in","start":139.585},{"text":"town","start":139.803},{"text":"is","start":140.02},{"text":"still","start":140.238},{"text":"switched","start":140.455},{"text":"on.","start":140.673},{"text":"All","start":140.89},{"text":"they","start":141.108},{"text":"make","start":141.325},{"text":"now","start":141.543},{"text":"is","start":141.76},{"text":"heat.","start":141.978}]},{"text":"Every screen is still on too. Nobody can read a single one.","show":144.9,"hide":148.85,"words":[{"text":"Every","start":144.9},{"text":"screen","start":145.13},{"text":"is","start":145.361},{"text":"still","start":145.591},{"text":"on","start":145.822},{"text":"too.","start":146.052},{"text":"Nobody","start":146.283},{"text":"can","start":146.513},{"text":"read","start":146.743},{"text":"a","start":146.974},{"text":"single","start":147.204},{"text":"one.","start":147.435}]}]},{"id":"road","n":13,"section":2,"title":false,"first":150.25,"end":166.2,"caps":[{"text":"On the road, every driver went blind at the same moment. Most of them stopped.","show":150.25,"hide":155.15,"words":[{"text":"On","start":150.25},{"text":"the","start":150.479},{"text":"road,","start":150.707},{"text":"every","start":150.936},{"text":"driver","start":151.165},{"text":"went","start":151.393},{"text":"blind","start":151.622},{"text":"at","start":151.851},{"text":"the","start":152.079},{"text":"same","start":152.308},{"text":"moment.","start":152.537},{"text":"Most","start":152.765},{"text":"of","start":152.994},{"text":"them","start":153.223},{"text":"stopped.","start":153.451}]},{"text":"One of them is trying to keep going, by feel.","show":156.75,"hide":160,"words":[{"text":"One","start":156.75},{"text":"of","start":156.978},{"text":"them","start":157.205},{"text":"is","start":157.433},{"text":"trying","start":157.66},{"text":"to","start":157.888},{"text":"keep","start":158.115},{"text":"going,","start":158.343},{"text":"by","start":158.57},{"text":"feel.","start":158.798}]},{"text":"Sound takes 1.5 seconds to cross the ice to you.","show":162.8,"hide":166.2,"words":[{"text":"Sound","start":162.8},{"text":"takes","start":163.038},{"text":"1.5","start":163.276},{"text":"seconds","start":163.514},{"text":"to","start":163.752},{"text":"cross","start":163.99},{"text":"the","start":164.228},{"text":"ice","start":164.466},{"text":"to","start":164.704},{"text":"you.","start":164.942}]}]},{"id":"slide","n":14,"section":2,"title":false,"first":167.4,"end":176.3,"caps":[{"text":"The car it hit went through the railing.","show":167.4,"hide":170.4,"words":[{"text":"The","start":167.4},{"text":"car","start":167.663},{"text":"it","start":167.925},{"text":"hit","start":168.188},{"text":"went","start":168.45},{"text":"through","start":168.713},{"text":"the","start":168.975},{"text":"railing.","start":169.238}]},{"text":"It's out on the lake now. Its engine is still running.","show":172.6,"hide":176.3,"words":[{"text":"It's","start":172.6},{"text":"out","start":172.835},{"text":"on","start":173.071},{"text":"the","start":173.306},{"text":"lake","start":173.542},{"text":"now.","start":173.777},{"text":"Its","start":174.013},{"text":"engine","start":174.248},{"text":"is","start":174.484},{"text":"still","start":174.719},{"text":"running.","start":174.955}]}]},{"id":"ice","n":15,"section":2,"title":false,"first":177.5,"end":191.15,"caps":[{"text":"Clear ice 5 cm thick can hold a person. A car needs about 20.","show":177.5,"hide":181.55,"words":[{"text":"Clear","start":177.5},{"text":"ice","start":177.703},{"text":"5","start":177.905},{"text":"cm","start":178.108},{"text":"thick","start":178.31},{"text":"can","start":178.513},{"text":"hold","start":178.715},{"text":"a","start":178.918},{"text":"person.","start":179.12},{"text":"A","start":179.323},{"text":"car","start":179.525},{"text":"needs","start":179.728},{"text":"about","start":179.93},{"text":"20.","start":180.133}]},{"text":"Where the stream comes in, the ice is only 8.","show":182.95,"hide":186.2,"words":[{"text":"Where","start":182.95},{"text":"the","start":183.177},{"text":"stream","start":183.405},{"text":"comes","start":183.633},{"text":"in,","start":183.86},{"text":"the","start":184.087},{"text":"ice","start":184.315},{"text":"is","start":184.543},{"text":"only","start":184.77},{"text":"8.","start":184.998}]},{"text":"It's going through.","show":189.2,"hide":191.15,"words":[{"text":"It's","start":189.2},{"text":"going","start":189.655},{"text":"through.","start":190.11}]}]},{"id":"steam","n":16,"section":2,"title":false,"first":193.15,"end":203.9,"caps":[{"text":"Lake water under ice is at 0 °C. That's 12 degrees warmer than the air.","show":193.15,"hide":197.7,"words":[{"text":"Lake","start":193.15},{"text":"water","start":193.362},{"text":"under","start":193.575},{"text":"ice","start":193.787},{"text":"is","start":193.999},{"text":"at","start":194.212},{"text":"0","start":194.424},{"text":"°C.","start":194.636},{"text":"That's","start":194.849},{"text":"12","start":195.061},{"text":"degrees","start":195.273},{"text":"warmer","start":195.486},{"text":"than","start":195.698},{"text":"the","start":195.91},{"text":"air.","start":196.123}]},{"text":"To a heat camera, the hole glows. To everyone out here, it is invisible.","show":199.3,"hide":203.9,"words":[{"text":"To","start":199.3},{"text":"a","start":199.53},{"text":"heat","start":199.76},{"text":"camera,","start":199.99},{"text":"the","start":200.22},{"text":"hole","start":200.45},{"text":"glows.","start":200.68},{"text":"To","start":200.91},{"text":"everyone","start":201.14},{"text":"out","start":201.37},{"text":"here,","start":201.6},{"text":"it","start":201.83},{"text":"is","start":202.06},{"text":"invisible.","start":202.29}]}]},{"id":"world","n":17,"section":2,"title":false,"first":205.7,"end":219.1,"caps":[{"text":"Right now, 8 billion people are blind.","show":205.7,"hide":208.6,"words":[{"text":"Right","start":205.7},{"text":"now,","start":205.99},{"text":"8","start":206.28},{"text":"billion","start":206.57},{"text":"people","start":206.86},{"text":"are","start":207.15},{"text":"blind.","start":207.44}]},{"text":"Every plant on Earth just stopped making food. They live on exactly this light.","show":209.8,"hide":214.75,"words":[{"text":"Every","start":209.8},{"text":"plant","start":210.048},{"text":"on","start":210.295},{"text":"Earth","start":210.543},{"text":"just","start":210.79},{"text":"stopped","start":211.038},{"text":"making","start":211.285},{"text":"food.","start":211.533},{"text":"They","start":211.78},{"text":"live","start":212.028},{"text":"on","start":212.275},{"text":"exactly","start":212.523},{"text":"this","start":212.77},{"text":"light.","start":213.018}]},{"text":"And every plane in the sky is still flying.","show":215.95,"hide":219.1,"words":[{"text":"And","start":215.95},{"text":"every","start":216.195},{"text":"plane","start":216.44},{"text":"in","start":216.685},{"text":"the","start":216.93},{"text":"sky","start":217.175},{"text":"is","start":217.42},{"text":"still","start":217.665},{"text":"flying.","start":217.91}]}]},{"id":"plane","n":18,"section":2,"title":false,"first":220.5,"end":229.25,"caps":[{"text":"This one is 12 km from its runway, 630 metres up.","show":220.5,"hide":223.95,"words":[{"text":"This","start":220.5},{"text":"one","start":220.72},{"text":"is","start":220.939},{"text":"12","start":221.159},{"text":"km","start":221.378},{"text":"from","start":221.598},{"text":"its","start":221.817},{"text":"runway,","start":222.037},{"text":"630","start":222.256},{"text":"metres","start":222.476},{"text":"up.","start":222.695}]},{"text":"Its pilots can't read a single instrument.","show":226.15,"hide":229.25,"words":[{"text":"Its","start":226.15},{"text":"pilots","start":226.46},{"text":"can't","start":226.77},{"text":"read","start":227.08},{"text":"a","start":227.39},{"text":"single","start":227.7},{"text":"instrument.","start":228.01}]}]},{"id":"sing","n":19,"section":2,"title":false,"first":230.85,"end":240.15,"caps":[{"text":"Lake ice cracks as it cools, and the sound runs through it for kilometres.","show":230.85,"hide":235.55,"words":[{"text":"Lake","start":230.85},{"text":"ice","start":231.085},{"text":"cracks","start":231.32},{"text":"as","start":231.555},{"text":"it","start":231.79},{"text":"cools,","start":232.025},{"text":"and","start":232.26},{"text":"the","start":232.495},{"text":"sound","start":232.73},{"text":"runs","start":232.965},{"text":"through","start":233.2},{"text":"it","start":233.435},{"text":"for","start":233.67},{"text":"kilometres.","start":233.905}]},{"text":"In the dark, it's the only map you have.","show":237.15,"hide":240.15,"words":[{"text":"In","start":237.15},{"text":"the","start":237.383},{"text":"dark,","start":237.617},{"text":"it's","start":237.85},{"text":"the","start":238.083},{"text":"only","start":238.317},{"text":"map","start":238.55},{"text":"you","start":238.783},{"text":"have.","start":239.017}]}]},{"id":"water","n":20,"section":3,"title":false,"first":242.55,"end":257.85,"caps":[{"text":"Someone is in the water.","show":242.55,"hide":244.75,"words":[{"text":"Someone","start":242.55},{"text":"is","start":242.858},{"text":"in","start":243.166},{"text":"the","start":243.474},{"text":"water.","start":243.782}]},{"text":"The driver got out of the car. He's holding on to the edge of the ice.","show":246.55,"hide":251.05,"words":[{"text":"The","start":246.55},{"text":"driver","start":246.747},{"text":"got","start":246.944},{"text":"out","start":247.141},{"text":"of","start":247.338},{"text":"the","start":247.534},{"text":"car.","start":247.731},{"text":"He's","start":247.928},{"text":"holding","start":248.125},{"text":"on","start":248.322},{"text":"to","start":248.519},{"text":"the","start":248.716},{"text":"edge","start":248.913},{"text":"of","start":249.109},{"text":"the","start":249.306},{"text":"ice.","start":249.503}]},{"text":"In water at 0 °C, you have 1 minute to get your breath back. About 10 before your arms stop working.","show":252.45,"hide":257.85,"words":[{"text":"In","start":252.45},{"text":"water","start":252.63},{"text":"at","start":252.81},{"text":"0","start":252.99},{"text":"°C,","start":253.17},{"text":"you","start":253.35},{"text":"have","start":253.53},{"text":"1","start":253.71},{"text":"minute","start":253.89},{"text":"to","start":254.07},{"text":"get","start":254.25},{"text":"your","start":254.43},{"text":"breath","start":254.61},{"text":"back.","start":254.79},{"text":"About","start":254.97},{"text":"10","start":255.15},{"text":"before","start":255.33},{"text":"your","start":255.51},{"text":"arms","start":255.69},{"text":"stop","start":255.87},{"text":"working.","start":256.05}]}]},{"id":"crawl","n":21,"section":3,"title":false,"first":259.45,"end":274.15,"caps":[{"text":"Standing, you press on the ice through two blades. Lying flat, through your whole body.","show":259.45,"hide":264.8,"words":[{"text":"Standing,","start":259.45},{"text":"you","start":259.7},{"text":"press","start":259.949},{"text":"on","start":260.199},{"text":"the","start":260.449},{"text":"ice","start":260.698},{"text":"through","start":260.948},{"text":"two","start":261.198},{"text":"blades.","start":261.447},{"text":"Lying","start":261.697},{"text":"flat,","start":261.947},{"text":"through","start":262.196},{"text":"your","start":262.446},{"text":"whole","start":262.696},{"text":"body.","start":262.945}]},{"text":"She's holding your ankles. You crawl towards the sound.","show":266.4,"hide":270.15,"words":[{"text":"She's","start":266.4},{"text":"holding","start":266.692},{"text":"your","start":266.983},{"text":"ankles.","start":267.275},{"text":"You","start":267.567},{"text":"crawl","start":267.858},{"text":"towards","start":268.15},{"text":"the","start":268.442},{"text":"sound.","start":268.733}]},{"text":"He's 40 metres away.","show":272.15,"hide":274.15,"words":[{"text":"He's","start":272.15},{"text":"40","start":272.5},{"text":"metres","start":272.85},{"text":"away.","start":273.2}]}]},{"id":"edge","n":22,"section":3,"title":false,"first":275.75,"end":289.2,"caps":[{"text":"The ice cracks under your hands.","show":275.75,"hide":278.35,"words":[{"text":"The","start":275.75},{"text":"ice","start":276.053},{"text":"cracks","start":276.357},{"text":"under","start":276.66},{"text":"your","start":276.963},{"text":"hands.","start":277.267}]},{"text":"Cracking isn't breaking. Not yet.","show":280.35,"hide":283,"words":[{"text":"Cracking","start":280.35},{"text":"isn't","start":280.721},{"text":"breaking.","start":281.092},{"text":"Not","start":281.463},{"text":"yet.","start":281.834}]},{"text":"He's been in the water for 6 minutes. You're 3 metres from the edge.","show":284.8,"hide":289.2,"words":[{"text":"He's","start":284.8},{"text":"been","start":285.02},{"text":"in","start":285.24},{"text":"the","start":285.46},{"text":"water","start":285.68},{"text":"for","start":285.9},{"text":"6","start":286.12},{"text":"minutes.","start":286.34},{"text":"You're","start":286.56},{"text":"3","start":286.78},{"text":"metres","start":287},{"text":"from","start":287.22},{"text":"the","start":287.44},{"text":"edge.","start":287.66}]}]},{"id":"reach","n":23,"section":3,"title":false,"first":290.8,"end":299.2,"caps":[{"text":"You reach out. Your fingers find his sleeve.","show":290.8,"hide":294,"words":[{"text":"You","start":290.8},{"text":"reach","start":291.08},{"text":"out.","start":291.36},{"text":"Your","start":291.64},{"text":"fingers","start":291.92},{"text":"find","start":292.2},{"text":"his","start":292.48},{"text":"sleeve.","start":292.76}]},{"text":"And the ice under your chest starts to bend.","show":296,"hide":299.2,"words":[{"text":"And","start":296},{"text":"the","start":296.249},{"text":"ice","start":296.498},{"text":"under","start":296.747},{"text":"your","start":296.996},{"text":"chest","start":297.244},{"text":"starts","start":297.493},{"text":"to","start":297.742},{"text":"bend.","start":297.991}]}]},{"id":"question","n":24,"section":3,"title":false,"first":300.8,"end":303.15,"caps":[{"text":"Would you crawl any closer?","show":300.8,"hide":303.15,"words":[{"text":"Would","start":300.8},{"text":"you","start":301.129},{"text":"crawl","start":301.458},{"text":"any","start":301.787},{"text":"closer?","start":302.116}]}]}]};
